 "content": "def transform(grid):
    # The vertical 2 marker points to the 9 component immediately above it;
    # recolor that aligned component as the marker.
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if out[r][c] != 9 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and out[yy][xx] == 9 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            components.append(comp)
    # Select component nearest to the upper endpoint of the longest vertical 2 run.
    twos = [(r,c) for r in range(h) for c in range(w) if out[r][c] == 2]
    runs = []
    for c in range(w):
        rr = [r for r in range(h) if out[r][c] == 2]
        if len(rr) >= 2 and rr == list(range(min(rr), max(rr)+1)):
            runs.append((len(rr), c, min(rr)))
    if components and runs:
        _, col, top = max(runs)
        comp = min(components, key=lambda cp: min(abs(c-col)+abs(r-top) for r,c in cp))
        for r,c in comp:
            out[r][c] = 2
    return out

