            e = c + 1
            while e < w and out[r][e] == out[r][c]: e += 1
            if out[r][c] != 0 and e-c > best_len:
                best_len, key_color = e-c, out[r][c]
                key_cells = [(r,x) for x in range(c,e)]
            c = e
    for c in range(w):
        r = 0
        while r < h:
            e = r + 1
            while e < h and out[e][c] == out[r][c]: e += 1
            if out[r][c] != 0 and e-r > best_len:
                best_len, key_color = e-r, out[r][c]
                key_cells = [(y,c) for y in range(r,e)]
            r = e
    seen=set(); motifs=[]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 9 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and out[yy][xx]==9 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            motifs.append(cells)
    if motifs and key_color is not None:
        target=min(motifs,key=lambda cells:min(abs(y-gy)+abs(x-gx) for y,x in cells for gy,gx in key_cells))
        for y,x in target: out[y][x]=key_color
    return out

