 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    bg=max(range(10),key=lambda v:sum(row.count(v) for row in out))
    # Connected components by color.
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=out[r][c]
            if color==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and out[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((color,cells))
    # Select the largest L-like component: one long horizontal and vertical arm.
    guides=[]
    for color,cells in comps:
        rows={r for r,c in cells}; cols={c for r,c in cells}
        hr=max((sum(1 for rr,cc in cells if rr==r) for r in rows),default=0)
        vr=max((sum(1 for rr,cc in cells if cc==c) for c in cols),default=0)
        if hr>=3 and vr>=3 and len(cells)<=hr+vr+2:
            guides.append((color,cells))
    if not guides: return out
    guide_color,guide=max(guides,key=lambda item:len(item[1]))
    # Cast outward rays from each end of the guide arms. The first other object
    # encountered is the target; recolor its entire connected component.
    guide_set=set(guide)
    target_color=None; target_seed=None; best_dist=None
    for r,c in guide:
        # Each ray starts at a guide cell and proceeds outward along row/column.
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and (nr,nc) in guide_set: continue
            y,x=nr,nc; dist=1
            while 0<=y<h and 0<=x<w:
                if out[y][x]!=bg and (y,x) not in guide_set:
                    if target_color is None or dist<best_dist:
                        target_color=out[y][x]; target_seed=(y,x); best_dist=dist
                    break
                y+=dr; x+=dc; dist+=1
    if target_seed is None: return out
    # Expand target seed to its entire same-color 4-connected component.
    color=target_color; stack=[target_seed]; seen={target_seed}; cells=[]
    while stack:
        y,x=stack.pop(); cells.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and out[yy][xx]==color and (yy,xx) not in seen:
                seen.add((yy,xx)); stack.append((yy,xx))
    for y,x in cells: out[y][x]=guide_color
    return out

