 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    bg = max(range(10), key=lambda color: sum(row.count(color) for row in out))
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = out[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and out[yy][xx] == color
                            and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            components.append((color, cells))
    # Find the longest vertical non-background component and trace upward
    # from its upper endpoint to the first distinct colored component.
    vertical = []
    for color, cells in components:
        rows = [r for r, c in cells]
        cols = [c for r, c in cells]
        if len(set(cols)) == 1 and max(rows) - min(rows) + 1 == len(cells):
            vertical.append((len(cells), color, min(rows), cols[0]))
    if not vertical:
        return out
    _, guide_color, top, col = max(vertical)
    r = top - 1
    while r >= 0:
        value = out[r][col]
        if value != bg:
            if value != guide_color:
                target = next((cells for color, cells in components
                               if color == value and (r, col) in cells), None)
                if target:
                    for y, x in target:
                        out[y][x] = guide_color
            break
        r -= 1
    return out

